-- At most one dispatch attempt per capture; uncertain HTTP outcomes are reconciled, never resent.
CREATE TABLE build_dispatches (capture_id TEXT PRIMARY KEY REFERENCES publish_captures(id), status TEXT NOT NULL DEFAULT 'dispatching' CHECK(status IN ('dispatching','queued','uncertain','rejected')), run_id INTEGER UNIQUE CHECK(run_id > 0), requested_at TEXT NOT NULL, updated_at TEXT NOT NULL, requested_by TEXT NOT NULL, updated_by TEXT NOT NULL, CHECK((status = 'queued' AND run_id IS NOT NULL) OR (status != 'queued' AND run_id IS NULL)));
CREATE TRIGGER build_dispatch_ready BEFORE INSERT ON build_dispatches WHEN NOT EXISTS (SELECT 1 FROM publish_captures WHERE id = NEW.capture_id AND status = 'ready' AND expires_at > NEW.requested_at) BEGIN SELECT RAISE(ABORT, 'Capture is not ready for dispatch'); END;
CREATE TRIGGER build_dispatch_initial BEFORE INSERT ON build_dispatches WHEN NEW.status != 'dispatching' BEGIN SELECT RAISE(ABORT, 'Invalid initial dispatch state'); END;
CREATE TRIGGER build_dispatch_immutable BEFORE UPDATE ON build_dispatches WHEN NEW.capture_id IS NOT OLD.capture_id OR NEW.requested_at IS NOT OLD.requested_at OR NEW.requested_by IS NOT OLD.requested_by OR (OLD.run_id IS NOT NULL AND NEW.run_id IS NOT OLD.run_id) BEGIN SELECT RAISE(ABORT, 'Dispatch identity is immutable'); END;
CREATE TRIGGER build_dispatch_transition BEFORE UPDATE OF status ON build_dispatches WHEN NEW.status != OLD.status AND NOT ((OLD.status = 'dispatching' AND NEW.status IN ('queued','uncertain','rejected')) OR (OLD.status = 'uncertain' AND NEW.status = 'queued')) BEGIN SELECT RAISE(ABORT, 'Invalid dispatch transition'); END;
CREATE TRIGGER build_dispatch_audit_insert AFTER INSERT ON build_dispatches BEGIN INSERT INTO audit_log(actor,action,entity,created_at) VALUES(NEW.requested_by,'publish.build.requested','capture:' || NEW.capture_id,NEW.requested_at); END;
CREATE TRIGGER build_dispatch_audit_update AFTER UPDATE OF status ON build_dispatches WHEN NEW.status != OLD.status BEGIN INSERT INTO audit_log(actor,action,entity,created_at) VALUES(NEW.updated_by,'publish.build.' || NEW.status,'capture:' || NEW.capture_id,NEW.updated_at); END;
CREATE TRIGGER build_dispatch_no_delete BEFORE DELETE ON build_dispatches BEGIN SELECT RAISE(ABORT, 'Dispatch history is retained'); END;
